        return .{ .result = TrackSize{ .min_max = .{ .min = min_res.result, .max = max_res.result } } };
}

pub fn parseTrackSize(input: *css.Parser) css.Result(TrackSize) {
        if (input.tryParse(TrackBreadth.parse, .{}).asValue()) |breadth| {
            _ = &breadth;
            return .{ .result = TrackSize{ .track_breadth = breadth } };
        }
        if (input.tryParse(css.Parser.expectFunctionMatching, .{ "minmax" }).isOk()) {
            return input.parseNestedBlock(parseTrackSizeMinMax);
        }
        if (input.expectFunctionMatching("fit-content").asErr()) |e| {
            _ = &e;
            return .{ .err = e };
        }
        const len_res = input.parseNestedBlock(css.voidWrap(LengthPercentage, LengthPercentage.parse));
        if ((len_res == .err)) {
            return .{ .err = len_res.err };
        }
        return .{ .result = TrackSize{ .fit_content = len_res.result } };
}

pub fn toCssTrackSize(this_ts: *const TrackSize, dest: *css.Printer) css.PrintErr!void {
        switch (this_ts.*) {
.track_breadth => |breadth| {
_ = try breadth.toCss(dest);
},
.min_max => |mm| {
_ = try dest.writeStr("minmax(");
        _ = try mm.min.toCss(dest);
        _ = try dest.delim(44, false);
        _ = try mm.max.toCss(dest);
        _ = try dest.writeChar(41);
},
.fit_content => |len| {
_ = try dest.writeStr("fit-content(");
        _ = try len.toCss(dest);
        _ = try dest.writeChar(41);
},
}
}

pub fn parseTrackBreadth(input: *css.Parser) css.Result(TrackBreadth) {
        return parseTrackBreadthInternal(input, true);
}

pub fn parseTrackBreadthInternal(input: *css.Parser, allow_flex: bool) css.Result(TrackBreadth) {
        if (input.tryParse(LengthPercentage.parse, .{}).asValue()) |len| {
            _ = &len;
            return .{ .result = .{ .length = len } };
        }
        if (allow_flex) {
            if (input.tryParse(parseTrackBreadthFlex, .{}).asValue()) |flex| {
                _ = &flex;
                return .{ .result = .{ .flex = flex } };
            }
        }
        const location = input.currentSourceLocation();
        const ident = (switch (input.expectIdent()) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(ident, "auto")) {
            return .{ .result = .auto };
        } else {
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(ident, "min-content")) {
                return .{ .result = .min_content };
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(ident, "max-content")) {
                    return .{ .result = .max_content };
                }
            }
        }
        return .{ .err = location.newUnexpectedTokenError(.{ .ident = ident }) };
}

pub fn parseTrackBreadthFlex(input: *css.Parser) css.Result(CSSNumber) {
        const location = input.currentSourceLocation();
        const token = (switch (input.next()) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
        if ((token == .dimension)) {
            if ((bun.strings.eqlCaseInsensitiveASCIIICheckLength(token.dimension.unit, "fr") and ((if (@typeInfo(@TypeOf(token.dimension)) == .@"enum") @intFromEnum(token.dimension) else token.dimension.value) >= 0.0))) {
                return .{ .result = (if (@typeInfo(@TypeOf(token.dimension)) == .@"enum") @intFromEnum(token.dimension) else token.dimension.value) };
            }
        }
        return .{ .err = location.newUnexpectedTokenError(token) };
}

pub fn toCssTrackBreadth(this_tb: *const TrackBreadth, dest: *css.Printer) css.PrintErr!void {
        switch (this_tb.*) {
.auto => {
_ = try dest.writeStr("auto");
},
.min_content => {
_ = try dest.writeStr("min-content");
},
.max_content => {
_ = try dest.writeStr("max-content");
},
.length => |len| {
_ = try len.toCss(dest);
},
.flex => |flex| {
_ = css.serializer.serializeDimension(flex, "fr", dest);
},
}
}

pub fn serializeLineNames(names: []const CustomIdent, dest: *Printer) PrintErr!void {
        _ = try dest.writeChar(91);
        var first = true;
        _ = &first;
        for (cp_iter_slice(names)) |name| {
            _ = &name;
            if (first) {
                first = false;
            } else {
                _ = try dest.writeChar(32);
            }
            _ = try writeIdent((if (@typeInfo(@TypeOf(name)) == .@"enum") @intFromEnum(name) else name.value), dest);
        }
        _ = try dest.writeChar(93);
}

pub fn writeIdent(name: []const u8, dest: *Printer) PrintErr!void {
        var css_module_grid_enabled = false;
        _ = &css_module_grid_enabled;
        if (dest.css_module) |css_module| {
            _ = &css_module;
            css_module_grid_enabled = css_module.config.grid;
        }
        if (css_module_grid_enabled) {
            if (dest.css_module) |*css_module| {
                _ = &css_module;
                if ((css_module.*).config.pattern.segments.last()) |last| {
                    _ = &last;
                    if ((last != css.css_modules.Segment.local)) {
                        return try dest.addInvalidCssModulesPatternInGridError();
                    }
                }
            }
        }
        _ = try dest.writeIdent(name, css_module_grid_enabled);
}

pub fn parseLineNames(input: *css.Parser) css.Result(CustomIdentList) {
        if (input.expectSquareBracketBlock().asErr()) |e| {
            _ = &e;
            return .{ .err = e };
        }
        return input.parseNestedBlock(struct {

pub fn parse(i: *css.Parser) css.Result(CustomIdentList) {
            var values = CustomIdentList{  };
            _ = &values;
            while (input.tryParse(CustomIdent.parse, .{}).asValue()) |ident| {
                _ = bun.handleOom(values.append(i.allocator(), ident));
            }
            return .{ .result = values };
    }
}.parse);
}

pub fn parseGridTemplateAreas(input: *css.Parser) css.Result(GridTemplateAreas) {
        if (input.tryParse(struct {

pub fn parseNone(i: *css.Parser) css.Result(void) {
            return i.expectIdentMatching("none");
    }
}.parseNone, .{}).isOk()) {
            return .{ .result = .none };
        }
        var tokens: SmallList(OptStr,1) = .{};
        _ = &tokens;
        var row: u32 = 0;
        _ = &row;
        var columns: u32 = 0;
        _ = &columns;
        if (input.tryParse(css.Parser.expectString, .{}).asValue()) |s| {
            _ = &s;
            const parsed_columns = (switch (parseGridAreaString(input.allocator(), s, (&tokens))) {
.result => |v| v,
.err => {
return .{ input.newError(.qualified_rule_invalid) };
},
});
            if ((row == 0)) {
                columns = parsed_columns;
            } else {
                if ((parsed_columns != columns)) {
                    return .{ .err = input.newCustomError(.invalid_declaration) };
                }
            }
            row = (row + 1);
        }
        return .{ .result = .{ .areas = .{ .columns = columns, .areas = tokens } } };
}

pub fn parseGridAreaString(allocator: Allocator, s: []const u8, tokens: *SmallList(OptStr,1)) bun.Maybe(u32,void) {
        var area_str = s;
        _ = &area_str;
        var column: u32 = 0;
        _ = &column;
        while (true) {
            const rest = bun.strings.trim(area_str, *const GRID_HTML_SPACE_CHARACTERS_ARR);
            if ((rest.len == 0)) {
                if ((column == 0)) {
                    return .{ .err = .{} };
                }
                break;
            }
            column = (column + 1);
            if (bun.strings.startsWithChar(rest, 46)) {
                const idx = idx: {
                var i: usize = 0;
                _ = &i;
                while ((i < rest.len)) : (i = (i + 1)) {
                    if ((rest[@as(usize, @intCast(i))] != 46)) {
                        break :idx i;
                    }
                }
                break :idx rest.len;
};
                area_str = rest[idx..];
            }
            const starts_with_name_codepoint = brk: {
            if ((rest.len == 0)) {
                break :brk false;
            }
            break :brk isNameCodepoint(rest[0]);
};
            if ((!starts_with_name_codepoint)) {
                return .{ .err = .{} };
            }
            const token_len = token_len: {
            var i: usize = 0;
            _ = &i;
            while ((i < rest.len)) : (i = (i + 1)) {
                if ((!isNameCodepoint(rest[@as(usize, @intCast(i))]))) {
                    break :token_len i;
                }
            }
            break :token_len rest.len;
};
            const token = rest[0..token_len];
            _ = bun.handleOom(tokens.append(allocator, token));
            area_str = rest[token_len..];
        }
        return .{ .result = column };
}

pub fn isNameCodepoint(c: u8) bool {
        return (((((((c >= 97) and (c <= 122)) or ((c >= 65) and (c <= 90))) or (c == 95)) or ((c >= 48) and (c <= 57))) or (c == 45)) or (c >= 128));
}
